"use client";

import { PageHeader } from "@/components/common/page-header";
import { cn } from "@/lib/utils";
import Link from "next/link";
import { usePathname } from "next/navigation";

const TABS = [
  { href: "/settings", label: "General" },
  { href: "/settings/billing", label: "Billing" },
  { href: "/settings/team", label: "Team" },
  { href: "/settings/notifications", label: "Notifications" },
] as const;

export default function SettingsLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();

  return (
    <>
      <PageHeader
        title="Settings"
        subtitle="Manage your workspace preferences"
      />
      <div className="border-b border-border/50 mb-6 -mt-2">
        <nav className="flex items-center gap-1 overflow-x-auto">
          {TABS.map((tab) => {
            const active = pathname === tab.href;
            return (
              <Link
                key={tab.href}
                href={tab.href}
                className={cn(
                  "relative px-4 py-2.5 text-sm font-medium whitespace-nowrap transition-colors",
                  "after:absolute after:inset-x-3 after:bottom-[-1px] after:h-0.5 after:rounded-full after:transition-colors",
                  active
                    ? "text-foreground after:bg-primary"
                    : "text-muted-foreground hover:text-foreground after:bg-transparent"
                )}
              >
                {tab.label}
              </Link>
            );
          })}
        </nav>
      </div>
      {children}
    </>
  );
}

import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
  CardAction,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Avatar,
  AvatarImage,
  AvatarFallback,
} from "@/components/ui/avatar";
import { assignees } from "@/lib/mock/assignees";

const ROLE_LABELS: Record<string, string> = {
  owner: "Owner",
  designer: "Designer",
  developer: "Developer",
  pm: "Project Manager",
};

function getInitials(name: string): string {
  return name
    .split(" ")
    .map((n) => n[0] ?? "")
    .join("")
    .toUpperCase()
    .slice(0, 2);
}

export default function TeamSettingsPage() {
  return (
    <div className="space-y-6 max-w-2xl">
      {/* Team members */}
      <Card>
        <CardHeader className="border-b">
          <CardTitle>Team members</CardTitle>
          <CardDescription>{assignees.length} seats used</CardDescription>
          <CardAction>
            <Button size="sm">Invite member</Button>
          </CardAction>
        </CardHeader>
        <CardContent className="p-0">
          <ul>
            {assignees.map((member, idx) => (
              <li key={member.id}>
                <div className="flex items-center justify-between gap-4 px-4 py-3">
                  <div className="flex items-center gap-3">
                    <Avatar>
                      <AvatarImage
                        src={member.avatarUrl}
                        alt={member.name}
                      />
                      <AvatarFallback>
                        {getInitials(member.name)}
                      </AvatarFallback>
                    </Avatar>
                    <div>
                      <p className="text-sm font-medium leading-none">
                        {member.name}
                      </p>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {ROLE_LABELS[member.role] ?? member.role}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {member.role === "owner" && (
                      <Badge variant="secondary">Owner</Badge>
                    )}
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-7 text-xs text-muted-foreground hover:text-destructive"
                    >
                      Remove
                    </Button>
                  </div>
                </div>
                {idx < assignees.length - 1 && (
                  <div className="border-t border-border/50 mx-4" />
                )}
              </li>
            ))}
          </ul>
        </CardContent>
      </Card>

      {/* Flat-pricing wedge callout */}
      <Card className="bg-primary/5 border-primary/20">
        <CardContent className="pt-4 pb-4">
          <p className="text-base font-semibold text-foreground">
            Unlimited seats on all plans
          </p>
          <p className="mt-1 text-sm text-muted-foreground">
            Invite your whole team at no extra cost. We price by workspace, not
            per user.
          </p>
          <p className="mt-2 text-xs text-muted-foreground">
            Compared to ManyRequests, SPP, and Copilot — all charge per seat.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";

interface ToggleRow {
  id: string;
  label: string;
  description: string;
  defaultOn: boolean;
}

const EMAIL_TOGGLES: ToggleRow[] = [
  {
    id: "email_new_request",
    label: "New request submitted",
    description: "Get notified when a client submits a new request",
    defaultOn: true,
  },
  {
    id: "email_sla_warning",
    label: "Request approaching SLA",
    description: "Reminder when a request is within 24 hours of its deadline",
    defaultOn: true,
  },
  {
    id: "email_delivered",
    label: "Request delivered",
    description: "Confirmation when a request is marked as delivered",
    defaultOn: false,
  },
  {
    id: "email_digest",
    label: "Weekly digest",
    description: "Summary of activity sent every Monday morning",
    defaultOn: true,
  },
] as const;

const INAPP_TOGGLES: ToggleRow[] = [
  {
    id: "inapp_comment",
    label: "Comment on request",
    description: "When a client or team member adds a comment",
    defaultOn: true,
  },
  {
    id: "inapp_mention",
    label: "Mention in thread",
    description: "When someone @mentions you in a comment",
    defaultOn: true,
  },
  {
    id: "inapp_assignee",
    label: "Assignee changed",
    description: "When a request is reassigned to you",
    defaultOn: false,
  },
] as const;

function buildDefaults(rows: readonly ToggleRow[]): Record<string, boolean> {
  const result: Record<string, boolean> = {};
  for (const row of rows) {
    result[row.id] = row.defaultOn;
  }
  return result;
}

function NotificationRow({
  row,
  checked,
  onChange,
}: {
  row: ToggleRow;
  checked: boolean;
  onChange: (id: string, value: boolean) => void;
}) {
  return (
    <div className="flex items-start justify-between gap-4 py-3">
      <div className="min-w-0">
        <p className="text-sm font-medium leading-none">{row.label}</p>
        <p className="text-xs text-muted-foreground mt-1">{row.description}</p>
      </div>
      <Switch
        data-checked={checked}
        onCheckedChange={(c: boolean) => onChange(row.id, c)}
        className="shrink-0 mt-0.5"
      />
    </div>
  );
}

function Divider() {
  return <div className="border-t border-border/50" />;
}

export default function NotificationsSettingsPage() {
  const [emailState, setEmailState] = useState<Record<string, boolean>>(
    () => buildDefaults(EMAIL_TOGGLES)
  );
  const [inappState, setInappState] = useState<Record<string, boolean>>(
    () => buildDefaults(INAPP_TOGGLES)
  );

  function handleEmail(id: string, value: boolean) {
    setEmailState((prev) => ({ ...prev, [id]: value }));
  }

  function handleInapp(id: string, value: boolean) {
    setInappState((prev) => ({ ...prev, [id]: value }));
  }

  return (
    <div className="space-y-6 max-w-2xl">
      {/* Email notifications */}
      <Card>
        <CardHeader className="border-b">
          <CardTitle>Email notifications</CardTitle>
          <CardDescription>
            Emails sent to your account address
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-2 pb-2">
          {EMAIL_TOGGLES.map((row, idx) => (
            <div key={row.id}>
              <NotificationRow
                row={row}
                checked={emailState[row.id] ?? row.defaultOn}
                onChange={handleEmail}
              />
              {idx < EMAIL_TOGGLES.length - 1 && <Divider />}
            </div>
          ))}
        </CardContent>
      </Card>

      {/* In-app notifications */}
      <Card>
        <CardHeader className="border-b">
          <CardTitle>In-app notifications</CardTitle>
          <CardDescription>
            Alerts shown inside Clientloop
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-2 pb-2">
          {INAPP_TOGGLES.map((row, idx) => (
            <div key={row.id}>
              <NotificationRow
                row={row}
                checked={inappState[row.id] ?? row.defaultOn}
                onChange={handleInapp}
              />
              {idx < INAPP_TOGGLES.length - 1 && <Divider />}
            </div>
          ))}
        </CardContent>
      </Card>

      {/* Slack integration */}
      <Card>
        <CardHeader className="border-b">
          <CardTitle>Slack</CardTitle>
          <CardDescription>
            Get real-time updates in your Slack channel
          </CardDescription>
        </CardHeader>
        <CardContent className="pt-4 pb-4">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="size-9 rounded-lg bg-muted flex items-center justify-center">
                <svg
                  viewBox="0 0 24 24"
                  className="size-5 text-foreground"
                  fill="currentColor"
                  aria-hidden="true"
                >
                  <path d="M5.042 15.165a2.528 2.528 0 0 1-2.52 2.523A2.528 2.528 0 0 1 0 15.165a2.527 2.527 0 0 1 2.522-2.52h2.52v2.52zM6.313 15.165a2.527 2.527 0 0 1 2.521-2.52 2.527 2.527 0 0 1 2.521 2.52v6.313A2.528 2.528 0 0 1 8.834 24a2.528 2.528 0 0 1-2.521-2.522v-6.313zM8.834 5.042a2.528 2.528 0 0 1-2.521-2.52A2.528 2.528 0 0 1 8.834 0a2.528 2.528 0 0 1 2.521 2.522v2.52H8.834zM8.834 6.313a2.528 2.528 0 0 1 2.521 2.521 2.528 2.528 0 0 1-2.521 2.521H2.522A2.528 2.528 0 0 1 0 8.834a2.528 2.528 0 0 1 2.522-2.521h6.312zM18.956 8.834a2.528 2.528 0 0 1 2.522-2.521A2.528 2.528 0 0 1 24 8.834a2.528 2.528 0 0 1-2.522 2.521h-2.522V8.834zM17.688 8.834a2.528 2.528 0 0 1-2.523 2.521 2.527 2.527 0 0 1-2.52-2.521V2.522A2.527 2.527 0 0 1 15.165 0a2.528 2.528 0 0 1 2.523 2.522v6.312zM15.165 18.956a2.528 2.528 0 0 1 2.523 2.522A2.528 2.528 0 0 1 15.165 24a2.527 2.527 0 0 1-2.52-2.522v-2.522h2.52zM15.165 17.688a2.527 2.527 0 0 1-2.52-2.523 2.526 2.526 0 0 1 2.52-2.52h6.313A2.527 2.527 0 0 1 24 15.165a2.528 2.528 0 0 1-2.522 2.523h-6.313z" />
                </svg>
              </div>
              <div>
                <p className="text-sm font-medium">Slack</p>
                <p className="text-xs text-muted-foreground">Not connected</p>
              </div>
            </div>
            <Button variant="outline" size="sm">
              Connect Slack
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
